select
from t_camera_info a,t_dict_business b,t_std_region c,t_dict_business d
where 1 = 1
 and a.camera_id = #{cameraId, jdbcType=BIGINT}
 and a.camera_name like concat('%',#{cameraName, jdbcType=VARCHAR},'%')
 and a.alias_name like concat('%',#{aliasName, jdbcType=VARCHAR},'%')
 and a.record_id = #{recordId, jdbcType=BIGINT}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.channel_num = #{channelNum, jdbcType=INTEGER}
 and a.sms_id = #{smsId, jdbcType=INTEGER}
 and a.rms_id = #{rmsId, jdbcType=INTEGER}
 and a.vendor_id = #{vendorId, jdbcType=VARCHAR}
 and a.stream_type = #{streamType, jdbcType=INTEGER}
 and a.protocol_type = #{protocolType, jdbcType=INTEGER}
 and a.stream_type = #{streamType, jdbcType=INTEGER}
 and a.protocol_type = #{protocolType, jdbcType=INTEGER}
 and a.camera_ip like concat('%',#{cameraIp, jdbcType=VARCHAR},'%')
 and a.url = #{url, jdbcType=VARCHAR}
 and a.port = #{port, jdbcType=INTEGER}
 and a.camera_type = #{cameraType, jdbcType=INTEGER}
 and a.is_control = #{isControl, jdbcType=INTEGER}
and a.address = #{address, jdbcType=VARCHAR},
and a.latitude = #{latitude, jdbcType=VARCHAR},
and a.longitude = #{longitude, jdbcType=VARCHAR},
and b.dict_code = a.vendor_id
and d.dict_code = a.camera_type
and c.region_id = a.up_region_id

